#!/bin/sh
set -eu
installer_dir=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
if ! command -v python3 >/dev/null 2>&1; then
    printf '%s\n' 'Python 3.9 or newer is required. Install python3 using your Linux software manager, then run this installer again.'
    exit 1
fi
if ! python3 -c 'import sys; assert sys.version_info >= (3,9)' >/dev/null 2>&1; then
    printf '%s\n' 'Python 3.9 or newer is required. Update Python using your Linux software manager.'
    exit 1
fi
exec python3 -c "import base64,zlib;exec(compile(zlib.decompress(base64.b64decode('')),'<Terminal Games installer>','exec'))"
